import java.util.*;

class Solution {
  public boolean isValid(String code) {
    Deque<String> stack = new ArrayDeque<>();
    int i = 0, n = code.length();
    while (i < n) {
      if (i > 0 && stack.isEmpty()) return false;
      if (code.startsWith("<![CDATA[", i)) {
        if (stack.isEmpty()) return false;
        int end = code.indexOf("]]>", i + 9);
        if (end < 0) return false;
        i = end + 3;
      } else if (code.charAt(i) == '<') {
        int end = code.indexOf('>', i + 1);
        if (end < 0) return false;
        boolean closing = i + 1 < n && code.charAt(i + 1) == '/';
        String name = code.substring(i + (closing ? 2 : 1), end);
        if (name.length() < 1 || name.length() > 9) return false;
        for (int j = 0; j < name.length(); j++)
          if (name.charAt(j) < 'A' || name.charAt(j) > 'Z') return false;
        if (closing) {
          if (stack.isEmpty() || !stack.pop().equals(name)) return false;
        } else stack.push(name);
        i = end + 1;
      } else {
        if (stack.isEmpty()) return false;
        i++;
      }
    }
    return stack.isEmpty();
  }
}
